UPDATE companies SET description='Blueprint Custom Apparel was established in 2019 in Derry, New Hampshire. The company operates from its New England base, providing custom-branded apparel and promotional products to a range of organizational clients.

The shop specializes in screen printing and embroidery, producing custom sweatshirts, jackets, hats, T-shirts, and a variety of branded accessories such as outerwear, workwear, and safety gear. Its services cover the full decoration process, from artwork preparation to final stitching or ink application, serving both small-run and bulk orders.

Blueprint works with small businesses, schools, U.S. government agencies, universities, enterprises, and startups, supplying apparel for trade shows, corporate events, and everyday uniform programs. The customer list reflects a focus on institutional and commercial buyers seeking consistent branding across multiple garment types.

The company emphasizes a direct, account-based approach: each client is assigned a dedicated sales representative to manage orders from quote through delivery. Blueprint also highlights its commitment to materials, craftsmanship, and repeatable quality, positioning its New England production as a mark of local excellence.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Screen printing", "Embroidery", "Custom apparel manufacturing", "Promotional item decoration", "Branded accessory decoration", "Workwear decoration", "Safety gear decoration"], "industries": ["Small business", "Education", "Government", "Higher education", "Enterprise", "Startups", "Event marketing", "Corporate apparel", "Promotional products", "Workwear", "Safety equipment"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Dedicated sales representative assigned to each account", "Guaranteed top-tier materials and craftsmanship on every piece", "Consistent quality and service across repeat orders", "All decoration performed in New England", "Responsive, one-on-one customer communication"], "facts_used": ["Founded 2019 in Derry, NH -> /about", "Offers screen printing and embroidery -> /", "Serves small businesses, schools, government agencies, universities, enterprises, startups -> /", "Provides dedicated sales representative per account -> /", "Guarantees top-tier materials and craftsmanship -> /", "Emphasizes consistent quality and New England production -> /about", "LinkedIn URL -> db"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "Our mission is to elevate business identities through our comprehensive suite of services including screen printing, embroidery, and a diverse selection of promotional items.", "founded_year": "2019", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": ["https://www.linkedin.com/company/blueprintbrothers-llc/"], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='blueprint-custom-apparel' AND approved AND profile IS NULL;
UPDATE companies SET description='Mahogany House Woodworks, operating as Boise Custom Furniture, is based in Boise, Idaho, and was founded in 2001 by James Barrett. Barrett came from a construction and high-end home building background before turning his lifelong passion for woodworking into a full-time shop. The business began with a focus on custom furniture built to last, using responsibly sourced materials and clean building methods.

The company designs and builds a range of custom wood products including dining tables, coffee tables, beds, headboards, bookshelves, floating shelves, adjustable desks, workstations, and commercial furniture for restaurants. They also produce custom wood countertops, butcher blocks, and cutting boards, and offer furniture engraving.

Mahogany House serves residential clients throughout Idaho and surrounding areas, as well as commercial customers such as restaurants and offices. Past projects include large bookcases for homes, bar tops for commercial spaces, and custom cutting boards for gifts.

Barrett positions the shop as an alternative to mass-produced furniture, emphasizing handcrafted construction, responsible material use, and a collaborative design process that provides clients with updates and photos during fabrication. The company offers free quotes and aims to deliver furniture that fits the client''s budget and space.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom furniture design and build", "Wood countertop fabrication", "Butcher block and cutting board manufacturing", "Furniture engraving", "Commercial furniture for restaurants", "Adjustable desk fabrication", "Floating shelf fabrication", "Custom dining tables", "Custom beds and headboards", "Custom bookshelves and dressers", "Custom entryway tables", "Custom coffee tables"], "industries": ["Residential", "Commercial", "Restaurant", "Hospitality", "Office"], "materials": ["Maple", "Walnut"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Handcrafted construction using clean building methods", "Responsible material use, avoiding mass-produced throwaway furniture", "Collaborative design process with photo updates during fabrication", "Free quotes and budget-conscious custom work"], "facts_used": ["Founded 2001 -> db", "Headquarters Boise, Idaho -> db", "Owner James Barrett -> /", "Based out of Nampa, Idaho -> /", "Custom furniture design and build -> /", "Products: dining tables, countertops, cutting boards, etc. -> /", "Industries: residential, commercial, restaurant -> /", "Materials: maple, walnut -> / (reviews)", "Handcrafted methods -> /", "Free quote -> /", "Updates with pictures during crafting -> / (review)"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Mahogany House Woodworks has over 25 years of experience designing and building custom wood furniture", "founded_year": "2001", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "owner