UPDATE companies SET description='CK12 Designs operates from Oklahoma City, Oklahoma, where it produces custom handcrafted furniture. The company''s founding year and ownership structure are not publicly disclosed, but it emphasizes local employment, hiring Oklahomans to build each piece.

The shop specializes in modern industrial farmhouse designs, crafting items such as beam consoles, charcuterie boards, coffee tables, dining tables, entertainment consoles, mantels, and custom live‑edged tables. All pieces are built from solid recycled wood sourced from native Oklahoma trees that have died naturally, been removed by homeowners, or salvaged from warehouse demolitions; no particle board is used.

CK12 Designs sells directly to residential customers through its website, serving homeowners seeking one‑of‑a‑kind furniture and reclaimed lumber for personal projects.

The company states that its custom-made furniture is frequently less expensive than pre‑fabricated alternatives from large retailers, and it differentiates itself by using only solid reclaimed wood and local labor.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom furniture manufacturing", "Handcrafted woodworking", "Reclaimed lumber milling", "Furniture finishing"], "industries": ["Residential furniture", "Home furnishings"], "materials": ["Solid recycled wood", "Reclaimed lumber", "Native Oklahoma hardwoods"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Uses only solid recycled wood, never particle board", "Wood sourced from native Oklahoma trees that died naturally, were cut down by homeowners, or rescued from demolition", "Employs local Oklahomans for handcrafted production", "Custom furniture priced below big\u2011box store equivalents"], "facts_used": ["Location: Oklahoma City, Oklahoma -> db", "Produces custom handcrafted furniture -> db", "Uses solid recycled wood from native Oklahoma trees -> db", "Emphasis on Modern, Industrial Farmhouse Designs -> /", "Products include beam consoles, charcuterie boards, coffee tables, dining tables, entertainment consoles, mantels, custom live-edged tables, reclaimed lumber -> /", "Employs local Oklahomans -> db", "Custom furniture frequently less expensive than big-box pre-fab -> db"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Makers of Fine Handcrafted Custom Furniture", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='ck12-designs' AND approved AND profile IS NULL;
